const q = $input.first().json.query || {};
const c = String(q.c || '').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 12);
const sd = $getWorkflowStaticData('global');
const e = (sd.links || {})[c];
let location = '/ausfallrechner/';
if (e) {
  const p = [];
  if (e.haus) p.push('haus=' + encodeURIComponent(e.haus));
  if (e.plaetze) p.push('plaetze=' + e.plaetze);
  if (e.lid) p.push('lid=' + e.lid);
  location = '/ausfallrechner/' + (p.length ? '?' + p.join('&') : '');
}
return [{ json: { location } }];

const f = $input.first().json;
const email = String(f['E-Mail der Person'] || '').trim().toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) throw new Error('Ungültige E-Mail-Adresse');
const haus = String(f['Name des Hauses'] || '').replace(/\s+/g, ' ').trim().slice(0, 80);
let plaetze = parseInt(f['Anzahl Plätze'], 10);
if (!(plaetze >= 10 && plaetze <= 300)) plaetze = null;
return [{ json: { email, haus, plaetze } }];

const ctx = $('Prüfen').first().json;
const rec = $input.first().json;
const lid = rec && rec.data && rec.data.id && rec.data.id.record_id;
if (!lid) throw new Error('Person in Attio nicht gefunden oder angelegt');
const sd = $getWorkflowStaticData('global');
sd.links = sd.links || {};
// gleicher Link für dieselbe Person und dieselben Angaben
for (const [c, v] of Object.entries(sd.links)) {
  if (v.lid === lid && v.haus === ctx.haus && v.plaetze === ctx.plaetze) {
    return [{ json: { ...ctx, lid, code: c, url: 'https://klinovum.de/r/' + c, reused: true } }];
  }
}
const ALPHA = 'abcdefghjkmnpqrstuvwxyz23456789';
let code;
do {
  code = Array.from({ length: 6 }, () => ALPHA[Math.floor(Math.random() * ALPHA.length)]).join('');
} while (sd.links[code]);
sd.links[code] = { lid, haus: ctx.haus, plaetze: ctx.plaetze, created: new Date().toISOString() };
return [{ json: { ...ctx, lid, code, url: 'https://klinovum.de/r/' + code, reused: false } }];
